<?php
require_once 'config/config.php';$user=require_login();$id=(int)($_GET['id']??0);$s=db()->prepare("SELECT b.*,r.room_number,rt.name type_name FROM bookings b JOIN rooms r ON r.id=b.room_id JOIN room_types rt ON rt.id=r.room_type_id WHERE b.id=? AND b.user_id=?");$s->execute([$id,$user['id']]);$b=$s->fetch();if(!$b)exit('Booking not found');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$tx='DEMO-'.date('YmdHis').'-'.random_int(1000,9999);$pdo=db();$pdo->beginTransaction();$s=$pdo->prepare("UPDATE payments SET transaction_id=?,status='paid',paid_at=NOW() WHERE booking_id=? AND status='pending'");$s->execute([$tx,$id]);$s=$pdo->prepare("UPDATE bookings SET status='confirmed' WHERE id=? AND status='pending'");$s->execute([$id]);$pdo->commit();flash('success','Payment successful. Your booking is confirmed.');redirect('my_bookings.php');}
$title='Payment | '.APP_NAME;require 'partials_header.php';?>
<div class="page"><div class="panel auth"><h2>Complete Payment</h2><p>Booking <strong><?=e($b['booking_code'])?></strong></p><p><?=e($b['type_name'])?> · Room <?=e($b['room_number'])?></p><p><?=e($b['check_in'])?> → <?=e($b['check_out'])?></p><h2>NPR <?=number_format((float)$b['total_amount'])?></h2><div class="alert success">Demo payment mode is enabled for the academic project. No real card or wallet is charged.</div><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><button class="btn orange" style="width:100%">Pay & Confirm Booking</button></form></div></div><?php require 'partials_footer.php'; ?>
